                                                        Assign on People
                                                    </a>
                                                </span>
                                            }}
                                        </div>
                                    </CardContent>
                                </Card>
                            }}
                        </div>
                    } }
                    <div className="flex flex-wrap items-center gap-2">
                        <Input
                            className="h-8 w-56"
                            placeholder="New role"
                            value={newRole}
                            onChange={lambda (e: ChangeEvent) { newRole = e.target.value; }}
                            onKeyDown={lambda (e: KeyboardEvent) { if e.key
