            restProps[key] = props[key];
        }
    }

    computedClass = cn(
        _buttonVariants.call(
            None,
            {"variant": variant, "size": size, "className": props["className"]}
        )
    );

    if asChild {
        return
            <Slot.Root
                data-slot="button"
                data-variant={variant}
                data-size={size}
                className={computedClass}
                {**restProps}
            >
                {props["children"]}
            </Slot.Root>;
    }

    return
        <button
            data-slot="button"
            data-variant={variant}
            data-size={size}
            className={computedClass}
            {**restProps}
        >
            {props["children"]}
        </button>;
}

def:pub buttonVariants -> any {
    return _buttonVariants;
}
