    n = lines;
    if n < 1 { n = 1; }
    if n > 8 { n = 8; }
    return n;
}

def:pub Composer(
    value: str,
    busy: bool,
    categories: list,
    onSet: Callable[([str], None)],
    onSend: Callable[([str], None)],
    onStop: Callable[([], None)],
