                                            >
                                                <SelectTrigger
                                                    className="h-6 w-auto border-dashed px-2 text-xs text-muted-foreground"
                                                    size="sm"
                                                    title="Assign to a project"
                                                >
                                                    <SelectValue
                                                        placeholder="+ Assign"
                                                    />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    {for p in projects {
                                                        <SelectItem
                                                            key={jid(p)}
                                                            value={jid(p)}
                                                        >
                                                            {p.name}
                                                        </SelectItem>
                                                    }}
                                                </SelectContent>
                                            </Select>
                                        }}
                                    </div>
                                </TableCell>
                                <TableCell>
