        await reload();
        await reloadOpenAi();
    }

    async def applyKey -> None {
        if not keyInput.strip() { err = "enter a key first"; return; }
        busy = True;
        err = "";
        res: any = None;
        try {
            res = await set_anthropic_key(keyInput.strip());
        } except Exception {
            err = "save failed";
            busy = False;
            return;
        }
        if res and not res["ok"] {
            err = str(res["error"]);
        } else {
            keyInput = "";
        }
        busy = False;
        await reload();
    }

