```jac
"""Pomodoro + Calendar -- backend (def:pub RPC shape).

Single-user app; all endpoints are `def:pub`. See requirements.md.

Every function here is `def:pub`, which the jac-sv-endpoints skill
prescribes for bodies that never `visit` -- avoids `walker` shape's
GET-only registration (which was the source of 405 Method Not Allowed
in the earlier walker version) and gives clients direct return values
instead of `.reports[0]` unwrapping.
"""

import from datetime { datetime, timezone }


node Event {
    has year: int = 0,
        month: int = 0,
        day: int = 0,
        hour: int = 0,
        minute: int = 0,
        title: str = "",
        description: str = "",
        work_min: int = 25,
        break_min: int = 5,
        cycles: int = 1;
}


node Note {
    has text: str = "",
        created_at: str = "";
}


node Session {
    has event_id: str = "",
        phase: str = "work",
        cycle_ix: int = 0,
        running: bool = True,
        phase_started_at: str = "",
        phase_elapsed_before_pause: int = 0;
}


node Settings {
    has idle_text: str = "( :3 )=3";
}


def now_iso() -> str {
    return datetime.now(timezone.utc).isoformat();
}


def:pub list_events(year: int, month: int) -> list[Event] {
    return [
        e for e in [root-->][?:Event]
        if e.year == year and e.month == month
    ];
}


def:pub get_event(event_id: str) -> Event | None {
    for e in [root-->][?:Event] {
        if jid(e) == event_id { return e; }
    }
    return None;
}


def:pub create_event(
    year: int, month: int, day: int, hour: int, minute: int,
    title: str, description: str,
    work_min: int, break_min: int, cycles: int
) -> Event {
    ev = Event(
        year=year, month=month, day=day, hour=hour, minute=minute,
        title=title, description=description,
        work_min=work_min, break_min=break_min, cycles=cycles
    );
    root ++> ev;
    return ev;
}


def:pub update_event(
    event_id: str,
    year: int, month: int, day: int, hour: int, minute: int,
    title: str, description: str,
    work_min: int, break_min: int, cycles: int
) -> Event | None {
    for e in [root-->][?:Event] {
        if jid(e) == event_id {
            e.year = year;
            e.month = month;
            e.day = day;
            e.hour = hour;
            e.minute = minute;
            e.title = title;
            e.description = description;
            e.work_min = work_min;
            e.break_min = break_min;
            e.cycles = cycles;
            return e;
        }
    }
    return None;
}


def:pub add_note(event_id: str, text: str) -> Note | None {
    for e in [root-->][?:Event] {
        if jid(e) == event_id {
            n = Note(text=text, created_at=now_iso());
            e ++> n;
            return n;
        }
    }
    return None;
}


def:pub list_notes(event_id: str) -> list[Note] {
    for e in [root-->][?:Event] {
        if jid(e) == event_id {
            return [n for n in [e-->][?:Note]];
        }
    }
    return [];
}


def:pub start_pomodoro(event_id: str) -> Session {
    # Only one active session -- retire any running one first.
    for s in [root-->][?:Session] {
        if s.running or s.phase != "done" {
            s.running = False;
            s.phase = "done";
        }
    }
    new_s = Session(
        event_id=event_id,
        phase="work",
        cycle_ix=0,
        running=True,
        phase_started_at=now_iso(),
        phase_elapsed_before_pause=0
    );
    root ++> new_s;
    return new_s;
}


def:pub pause_pomodoro(session_id: str) -> Session | None {
    for s in [root-->][?:Session] {
        if jid(s) == session_id and s.running {
            elapsed_now = int(
                (datetime.now(timezone.utc)
                 - datetime.fromisoformat(s.phase_started_at)
                ).total_seconds()
            );
            s.phase_elapsed_before_pause += elapsed_now;
            s.running = False;
            return s;
        }
    }
    return None;
}


def:pub resume_pomodoro(session_id: str) -> Session | None {
    for s in [root-->][?:Session] {
        if jid(s) == session_id and not s.running and s.phase != "done" {
            s.phase_started_at = now_iso();
            s.running = True;
            return s;
        }
    }
    return None;
}


def:pub stop_pomodoro(session_id: str) -> Session | None {
    for s in [root-->][?:Session] {
        if jid(s) == session_id {
            s.running = False;
            s.phase = "done";
            return s;
        }
    }
    return None;
}


"""Called by the client when its derived countdown hits 0.

Server owns the state transition so multiple tabs stay consistent.
Cycle model (cycles = N): work[0] break work[1] break ... work[N-1] done."""
def:pub advance_phase(session_id: str) -> Session | None {
    for s in [root-->][?:Session] {
        if jid(s) == session_id {
            ev_cycles = 1;
            for e in [root-->][?:Event] {
                if jid(e) == s.event_id {
                    ev_cycles = e.cycles;
                    break;
                }
            }
            if s.phase == "work" {
                if s.cycle_ix < ev_cycles - 1 {
                    s.phase = "break";
                } else {
                    s.phase = "done";
                    s.running = False;
                }
            } elif s.phase == "break" {
                s.cycle_ix += 1;
                s.phase = "work";
            }
            s.phase_started_at = now_iso();
            s.phase_elapsed_before_pause = 0;
            return s;
        }
    }
    return None;
}


def:pub current_session() -> Session | None {
    for s in [root-->][?:Session] {
        if s.phase != "done" { return s; }
    }
    return None;
}


def:pub get_settings() -> Settings {
    for st in [root-->][?:Settings] { return st; }
    st = Settings();
    root ++> st;
    return st;
}


def:pub set_idle_text(text: str) -> Settings {
    for st in [root-->][?:Settings] {
        st.idle_text = text;
        return st;
    }
    st = Settings(idle_text=text);
    root ++> st;
    return st;
}
