"""PomodoroFloat -- fixed bottom-right widget; idle vs running vs expanded."""

import from endpoints {
    Event, Note, Session,
    pause_pomodoro, resume_pomodoro, stop_pomodoro, advance_phase,
    add_note, list_notes
}
import from .ui.button { Button }
import from .ui.textarea { Textarea }

import from react { useEffect }


def phase_duration_sec(session: Session, event: Event | None) -> int {
    if event is None { return 25 * 60; }
    if session.phase == "work" { return event.work_min * 60; }
    if session.phase == "break" { return event.break_min * 60; }
    return 0;
}


def:pub PomodoroFloat(
    session: Session | None,
    events: list[Event],
    idle_text: str,
    expanded: bool,
    onToggleExpand: Callable[[], None],
    onQuickStart: Callable[[], None],
    onSessionUpdated: Callable[[Session | None], None]
) -> JsxElement {
    has now_sec: int = 0;
    has notes: list[Note] = [];
    has note_draft: str = "";
    has posting_note: bool = False;

    useEffect(lambda {
        now_sec = int(Date.now() / 1000);
        handle = setInterval(lambda { now_sec = int(Date.now() / 1000); }, 1000);
        return lambda { clearInterval(handle); };
    }, []);

    async can with [session] entry {
        if session is None {
            notes = [];
        } else {
            notes = await list_notes(session.event_id);
        }
    }

    def owning_event -> Event | None {
        if session is None { return None; }
        for e in events {
            if jid(e) == session.event_id { return e; }
        }
        return None;
    }

    def compute_remaining -> int {
        if session is None { return 0; }
        ev = owning_event();
        total = phase_duration_sec(session, ev);
        started_sec = int(Date.parse(session.phase_started_at) / 1000);
        elapsed = session.phase_elapsed_before_pause;
        if session.running {
            elapsed = elapsed + (now_sec - started_sec);
        }
        left = total - elapsed;
        return left if left > 0 else 0;
    }

    async def check_expiry -> None {
        if session is not None and session.running and session.phase != "done" {
            if compute_remaining() <= 0 {
                updated = await advance_phase(jid(session));
                if updated is not None { onSessionUpdated(updated); }
            }
        }
    }

    # Fire expiry check when the derived timer hits 0.
    can with [now_sec] entry {
        check_expiry();
    }

    async def pause -> None {
        if session is not None {
            updated = await pause_pomodoro(jid(session));
            if updated is not None { onSessionUpdated(updated); }
        }
    }

    async def resume -> None {
        if session is not None {
            updated = await resume_pomodoro(jid(session));
            if updated is not None { onSessionUpdated(updated); }
        }
    }

    async def stop -> None {
        if session is not None {
            await stop_pomodoro(jid(session));
            onSessionUpdated(None);
        }
    }

    def set_draft(e: ChangeEvent) -> None { note_draft = e.target.value; }

    async def post_note -> None {
        if session is None or not note_draft.strip() { return; }
        posting_note = True;
        n = await add_note(session.event_id, note_draft);
        if n is not None { notes = [n] + notes; }
        note_draft = "";
        posting_note = False;
    }

    is_running = session is not None and session.phase != "done";
    remaining = compute_remaining();
    ev = owning_event();

    if is_running and expanded {
        return <div className="fixed bottom-4 right-4 z-40 w-80 bg-background border border-border rounded-lg shadow-lg p-4 flex flex-col gap-3">
            <div className="flex justify-between items-start">
                <div>
                    <div className="text-xs uppercase text-muted-foreground tracking-wide">
                        {session.phase}
                        {" -- cycle " + str(session.cycle_ix + 1)}
                        {(" / " + str(ev.cycles)) if ev is not None else ""}
                    </div>
                    <div className="text-sm font-semibold">
                        {ev.title if ev is not None else "Session"}
                    </div>
                </div>
                <button
                    className="text-xs text-muted-foreground hover:text-foreground"
                    onClick={onToggleExpand}
                >
                    Minimize
                </button>
            </div>

            <div className="text-5xl font-mono tabular-nums text-center py-2">
                {f"{remaining // 60:02}:{remaining % 60:02}"}
            </div>

            {if ev is not None and ev.description {
                <p className="text-xs text-muted-foreground italic">
                    {ev.description}
                </p>
            }}

            <div className="flex gap-2 justify-center">
                {if session.running {
                    <Button size="sm" variant="outline" onClick={pause}>Pause</Button>
                } else {
                    <Button size="sm" onClick={resume}>Play</Button>
                }}
                <Button size="sm" variant="outline" onClick={stop}>Stop</Button>
            </div>

            <div className="flex flex-col gap-2 pt-2 border-t border-border">
                <span className="text-xs uppercase text-muted-foreground tracking-wide">
                    Notes
                </span>
                <Textarea
                    value={note_draft}
                    onChange={set_draft}
                    placeholder="What did you just accomplish?"
                    rows={2}
                />
                <Button
                    size="sm"
                    onClick={post_note}
                    disabled={posting_note or not note_draft.strip()}
                >
                    Add note
                </Button>
                <div className="flex flex-col gap-1 max-h-32 overflow-y-auto">
                    {for n in notes {
                        <div key={n.created_at + n.text} className="text-xs p-2 rounded border border-border">
                            {n.text}
                        </div>
                    }}
                </div>
            </div>
        </div>;
    }
    if is_running {
        return <button
            className="fixed bottom-4 right-4 z-40 bg-primary text-primary-foreground rounded-full px-4 py-3 shadow-lg font-mono tabular-nums hover:opacity-90"
            onClick={onToggleExpand}
        >
            {f"{remaining // 60:02}:{remaining % 60:02}"}
        </button>;
    }
    return <div className="fixed bottom-4 right-4 z-40 flex flex-col items-end gap-2">
        {if expanded {
