"""MonthCalendar -- 6x7 grid with event dots; click day or event."""

import from endpoints { Event }
import from .ui.card { Card, CardContent }


def:pub MonthCalendar(
    year: int,
    month: int,
    today_day: int,
    days_in_month: int,
    first_weekday: int,
    events: list[Event],
    onSelectDay: Callable[[int], None],
    onOpenEvent: Callable[[Event], None]
) -> JsxElement {
    # Build a padded cell list: 0 = blank cell before/after the month.
    cells: list[int] = [0 for _ in range(first_weekday)];
    for d in range(1, days_in_month + 1) {
        cells = cells + [d];
    }
    # Pad to a full 6 rows (42 cells) so grid height is stable across months.
    while len(cells) < 42 {
        cells = cells + [0];
    }

    events_by_day: dict[int, list[Event]] = {};
    for e in events {
        bucket = events_by_day[e.day] if e.day in events_by_day else [];
        events_by_day[e.day] = bucket + [e];
    }

    def cell_class(d: int) -> str {
        if d == 0 {
            return "min-h-24 rounded-md border border-dashed border-border/40 bg-muted/20";
        }
        base = "min-h-24 rounded-md border p-2 flex flex-col gap-1 text-left transition-colors cursor-pointer";
        if d == today_day {
            return base + " border-primary bg-primary/5 hover:bg-primary/10";
        }
        return base + " border-border hover:bg-accent";
    }

    <Card>
        <CardContent className="p-3">
            <div className="grid grid-cols-7 gap-1 text-xs text-muted-foreground mb-2">
                {for label in ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"] {
                    <div key={label} className="text-center py-1 font-medium">
                        {label}
                    </div>
                }}
            </div>
            <div className="grid grid-cols-7 gap-1">
                {for (i, d) in enumerate(cells) {
                    if d == 0 {
                        <div key={"blank-" + str(i)} className={cell_class(d)}></div>
                    } else {
                        day_events = events_by_day[d] if d in events_by_day else [];
                        <div
                            key={"day-" + str(d)}
                            className={cell_class(d)}
                            onClick={lambda () { onSelectDay(d); }}
                        >
                            <span className={"text-sm font-medium " + ("text-primary" if d == today_day else "")}>
                                {str(d)}
                            </span>
                            <div className="flex flex-col gap-0.5 overflow-hidden">
                                {for ev in day_events[:3] {
                                    <button
                                        key={jid(ev)}
                                        className="text-xs truncate bg-primary/10 text-primary rounded px-1 py-0.5 hover:bg-primary/20 text-left"
                                        onClick={lambda (e: MouseEvent) {
                                            e.stopPropagation();
                                            onOpenEvent(ev);
                                        }}
                                    >
                                        {f"{ev.hour:02}:{ev.minute:02} " + ev.title}
                                    </button>
                                }}
                                {if len(day_events) > 3 {
                                    <span className="text-xs text-muted-foreground">
                                        {"+" + str(len(day_events) - 3) + " more"}
                                    </span>
                                }}
                            </div>
                        </div>
                    }
                }}
            </div>
        </CardContent>
    </Card>
}
