            <div id="wrap">
                <canvas id="glcanvas" width={960} height={600}></canvas>
                <div id="hud">
                    {"score "}
                    <b id="hud-score">0</b>
                    {" · "}
                    <b id="hud-fps">0</b>
                    {" fps"}
                </div>
            </div>
        </div>;
}

