    has gl: any = None,
        canvas: any = None,
        exports: any = None,
        mem: any = None,
        heap: any = 0,
        proj: list = [],
        mv: list = [],
        pstack: list = [],
        mvstack: list = [],
        mode: int = 0x1700,
        verts: list = [],
        color: list = [1.0, 1.0, 1.0, 1.0],
