"""WebGL shim for the rlgl/input externs of a wasm-compiled na game.

A reusable client library (the moral equivalent of raylib for the browser):
it emulates the scalar rlgl immediate-mode API + input on WebGL/DOM, supplies
the libc/__multi3 the Jac native runtime needs, instantiates /static/<name>.wasm,
and drives init()/frame() per requestAnimationFrame. Its client codespace is
inferred from its npm import and DOM usage - no marker needed.

The host-ABI surface (console write, abort) is the versioned jac_host1
contract supplied by @jac/wasm_host; this shim supplies only the game's own
raylib FFI (plus its legacy libc stubs under env)."""

import from "@jac/wasm_host" { instantiate_na_wasm }

obj Shim {
    has gl: any = None,
        canvas: any = None,
        exports: any = None,
        mem: any = None,
        heap: any = 0,
        proj: list = [],
        mv: list = [],
        pstack: list = [],
        mvstack: list = [],
        mode: int = 0x1700,
        verts: list = [],
        color: list = [1.0, 1.0, 1.0, 1.0],
        bmode: int = 4,
        vbo: any = None,
        aPos: int = 0,
        aCol: int = 0,
        uMVP: any = None,
        keys: dict = {},
        pressed: dict = {},
        mpressed: dict = {},
        mouseX: float = 0.0,
        mouseY: float = 0.0,
        locked: bool = False,
        dt: float = 0.016,
        time: float = 0.0,
        t0: float = 0.0,
        draws: int = 0,
        on_tick: any = None;
}

def _m_ident -> list { ... }

def _m_mul(a: list, b: list) -> list { ... }

def _m_translate(x: float, y: float, z: float) -> list { ... }

def _m_rotate(ang: float, x: float, y: float, z: float) -> list { ... }

def _m_frustum(l: float, r: float, b: float, t: float, n: float, f: float) -> list { ... }

def _m_ortho(l: float, r: float, b: float, t: float, n: float, f: float) -> list { ... }

def _cur(sh: any) -> list { ... }

def _setcur(sh: any, m: list) { ... }

def _read_cstr(sh: any, p: int) -> str { ... }

def _flush(sh: any) -> None { ... }

def _build_env(sh: any) -> dict { ... }

def _init_gl(sh: any) { ... }

def _keymap(code: str) -> int {
    m = {
        "KeyW": 87,
        "KeyA": 65,
        "KeyS": 83,
        "KeyD": 68,
        "Space": 32,
        "Tab": 258,
        "ArrowRight": 262,
        "ArrowLeft": 263,
        "ArrowDown": 264,
        "ArrowUp": 265
    };
    return m.get(code, 0);
}

def _install_input(sh: any) {
    window.addEventListener(
        "keydown",
        lambda (e: any) {
            kc = _keymap(e.code);
            if kc != 0 {
                e.preventDefault();
                sh.keys[kc] = 1;
                sh.pressed[kc] = 1;
            }
        }
    );
    window.addEventListener(
        "keyup",
        lambda (e: any) {
            kc = _keymap(e.code);
            if kc != 0 {
                sh.keys[kc] = 0;
            }
        }
    );
    sh.canvas.addEventListener("mousedown", lambda (e: any) { sh.mpressed[0] = 1; });
    document.addEventListener(
        "mousemove",
        lambda (e: any) { if sh.locked {
            sh.mouseX = sh.mouseX + e.movementX;
            sh.mouseY = sh.mouseY + e.movementY;
        } else {
            sh.mouseX = e.offsetX;
            sh.mouseY = e.offsetY;
        } }
    );
    document.addEventListener(
        "pointerlockchange",
        lambda (e: any) { sh.locked = document.pointerLockElement == sh.canvas; }
    );
}

def _frame_tick(sh: any, ts: float) {
    if sh.t0 == 0.0 {
        sh.t0 = ts;
    }
    now = (ts - sh.t0) / 1000.0;
    sh.dt = (now - sh.time) if sh.time > 0.0 else 0.016;
    if sh.dt > 0.05 {
        sh.dt = 0.05;
    }
    sh.time = now;
    closed = sh.exports.frame();
    # Optional per-frame hook so a page can drive a HUD (score/fps) without the
    # shim needing to know anything game-specific.
    if sh.on_tick is not None {
        fps = Math.round(1.0 / sh.dt) if sh.dt > 0.0 else 0;
        sh.on_tick(sh.exports, fps);
    }
    sh.pressed = {};
    sh.mpressed = {};
    if not closed {
        requestAnimationFrame(lambda (t2: float) { _frame_tick(sh, t2); });
    }
}

async def:pub run_game(canvas: any, on_tick: any = None) {
    sh = Shim();
    sh.on_tick = on_tick;
    sh.canvas = canvas;
    sh.gl = canvas.getContext("webgl");
    sh.proj = _m_ident();
    sh.mv = _m_ident();
    _init_gl(sh);
    _install_input(sh);
    # jac_host1 (console/os/time host surface) comes from the runtime; this
    # shim supplies only the game's raylib externs (and legacy libc stubs).
    inst: any = await instantiate_na_wasm(
        "/static/main.wasm", sh, {"env": _build_env(sh)}
    );
    inst.exports.init();
    requestAnimationFrame(lambda (ts: float) { _frame_tick(sh, ts); });
}
